);

CREATE TABLE IF NOT EXISTS "contratos" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"personal_id" BIGINT,
	"regimen_laboral_id" BIGINT,
	"tipo_contrato_id" BIGINT,
	"numero_contrato" VARCHAR(50),
	"fecha_contrato" DATE,
	"fecha_inicio" DATE,
	"fecha_fin" DATE,
	"estado_contrato_id" BIGINT,
	"observaciones" TEXT,
	PRIMARY KEY("id")
);